var TEXTS = [
  '一元二次方程求根公式',
  '2',
  'x²',
  ' + ',
  '4',
  'x ',
  '−6',
  ' = 0',
  'x = (−b ± √(b² − 4ac)) / (2a)',
  'a = 2',
  'b = 4',
  'c = −6',
  'Δ = b² − 4ac = 4² − 4·2·(−6) = 16 + 48 = 64',
  '方程',
  '求根公式',
  '判别式',
  '示意：依据题面给定条件重建'
];
const visual = {
  prepare: function (input) {
    return TEXTS.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 960;
    var H = (input && input.viewport && input.viewport.heightDu) || 620;
    var colors = {
      bg: '#f6f8fb',
      card: '#ffffff',
      line: '#d7e0ea',
      ink: '#203040',
      muted: '#5b6b7f',
      blue: '#1f6feb',
      green: '#0f8f5f',
      orange: '#d97706'
    };
    var paths = [];
    var children = [];
    function addPath(id, commands, style) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id };
      if (style) {
        if (style.stroke !== undefined && style.stroke !== null) node.stroke = style.stroke;
        if (style.fill !== undefined && style.fill !== null) node.fill = style.fill;
        if (style.strokeWidth !== undefined) node.strokeWidth = style.strokeWidth;
        if (style.dash) node.strokeDasharray = style.dash;
        if (style.opacity !== undefined) node.opacity = style.opacity;
      }
      children.push(node);
    }
    function rect(x, y, w, h, fill, stroke, sw) {
      addPath('r' + paths.length, visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]), { fill: fill, stroke: stroke, strokeWidth: sw });
    }
    function circle(cx, cy, r, fill, stroke, sw) {
      addPath('c' + paths.length, visualSdk.circle(cx, cy, r), { fill: fill, stroke: stroke, strokeWidth: sw });
    }
    function label(t, x, y, size, fill, anchor, family) {
      children.push({ type: 'label', text: t, x: x, y: y, fontSize: size, fill: fill, fontFamily: family || 'sans-serif', textAnchor: anchor || 'middle', dominantBaseline: 'middle' });
    }
    function estWidth(t, size) {
      var w = 0;
      for (var i = 0; i < t.length; i++) {
        var code = t.charCodeAt(i);
        w += code > 255 ? size * 0.95 : size * 0.62;
      }
      return w;
    }
    rect(0, 0, W, H, colors.bg, null, 0);
    label(TEXTS[0], W / 2, 38, 28, colors.ink, 'middle', 'sans-serif');
    rect(70, 62, W - 140, 148, colors.card, colors.line, 1.5);
    label(TEXTS[13], 92, 88, 16, colors.muted, 'start', 'sans-serif');
    var eqTokens = [
      { idx: 1, color: colors.blue, key: 'a' },
      { idx: 2, color: colors.ink },
      { idx: 3, color: colors.ink },
      { idx: 4, color: colors.green, key: 'b' },
      { idx: 5, color: colors.ink },
      { idx: 6, color: colors.orange, key: 'c' },
      { idx: 7, color: colors.ink }
    ];
    var eqFont = 40;
    var eqY = 150;
    var widths = [];
    var total = 0;
    for (var i = 0; i < eqTokens.length; i++) {
      var tw0 = estWidth(TEXTS[eqTokens[i].idx], eqFont);
      widths.push(tw0);
      total += tw0;
    }
    var x = (W - total) / 2;
    var centers = {};
    for (var j = 0; j < eqTokens.length; j++) {
      var tok = eqTokens[j];
      var tw = widths[j];
      var cx = x + tw / 2;
      if (tok.key) {
        var pad = 10;
        var fill = tok.key === 'a' ? '#e8f0fe' : (tok.key === 'b' ? '#e6f7ef' : '#fff1e6');
        rect(cx - tw / 2 - pad, eqY - 32, tw + pad * 2, 56, fill, tok.color, 2);
        centers[tok.key] = { x: cx, y: eqY };
        circle(cx, eqY + 30, 3, '#ffffff', tok.color, 2);
      }
      label(TEXTS[tok.idx], cx, eqY, eqFont, tok.color, 'middle', 'monospace');
      x += tw;
    }
    var cards = [
      { key: 'a', x: 80, y: 232, w: 240, h: 76, color: colors.blue, fill: '#eef4ff', labelIdx: 9 },
      { key: 'b', x: 360, y: 232, w: 240, h: 76, color: colors.green, fill: '#eefaf4', labelIdx: 10 },
      { key: 'c', x: 640, y: 232, w: 240, h: 76, color: colors.orange, fill: '#fff6ee', labelIdx: 11 }
    ];
    for (var k = 0; k < cards.length; k++) {
      var card = cards[k];
      var c0 = centers[card.key];
      if (!c0) continue;
      var ex = card.x + card.w / 2;
      var ey = card.y - 8;
      addPath('leader' + k, visualSdk.polyline([[c0.x, c0.y + 34], [c0.x, c0.y + 50], [ex, c0.y + 50], [ex, ey]]), { stroke: card.color, strokeWidth: 1.5, dash: '5 5', fill: 'none' });
    }
    for (var k2 = 0; k2 < cards.length; k2++) {
      var c2 = cards[k2];
      rect(c2.x, c2.y, c2.w, c2.h, c2.fill, c2.color, 1.5);
      rect(c2.x, c2.y, c2.w, 6, c2.color, null, 0);
      label(TEXTS[c2.labelIdx], c2.x + c2.w / 2, c2.y + c2.h / 2 + 4, 26, c2.color, 'middle', 'sans-serif');
    }
    rect(70, 338, W - 140, 92, colors.card, colors.line, 1.5);
    label(TEXTS[14], 92, 364, 16, colors.muted, 'start', 'sans-serif');
    label(TEXTS[8], W / 2, 394, 30, colors.ink, 'middle', 'serif');
    rect(70, 456, W - 140, 112, colors.card, colors.line, 1.5);
    label(TEXTS[15], 92, 482, 16, colors.muted, 'start', 'sans-serif');
    label(TEXTS[12], W / 2, 526, 22, colors.ink, 'middle', 'monospace');
    label(TEXTS[16], W / 2, 596, 13, colors.muted, 'middle', 'sans-serif');
    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula',
      revision: input && input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
